export function fmtPct(n: number, digits = 1): string {
  return `${n.toFixed(digits)}%`;
}

export function fmtUsd(n: number): string {
  if (Math.abs(n) >= 1_000_000_000) return `$${(n / 1_000_000_000).toFixed(1)}B`;
  if (Math.abs(n) >= 1_000_000) return `$${(n / 1_000_000).toFixed(0)}M`;
  if (Math.abs(n) >= 1_000) return `$${Math.round(n).toLocaleString("en-US")}`;
  return `$${Math.round(n)}`;
}

export function fmtB(n: number, digits = 1): string {
  return `$${n.toFixed(digits)}B`;
}

export function topStatesBy(
  key: "prevalenceDec2020Pct" | "totalBalanceDec2020M" | "meanBalanceDec2020" | "prevalenceAug2024Pct",
  n = 12,
): StateRow[] {
  return [...STATE_PANEL]
    .filter((s) => (key === "prevalenceAug2024Pct" ? s.prevalenceAug2024Pct != null : true))
    .sort((a, b) => {
      const av = (a[key] as number | null) ?? -1;
      const bv = (b[key] as number | null) ?? -1;
      return bv - av;
    })
    .slice(0, n);
}

