    ).map((s) => ({
      abbr: s.abbr,
      x: s.prevalenceDec2020Pct,
      y: s.meanBalanceDec2020,
      z: Math.sqrt(s.totalBalanceDec2020M),
      totalM: s.totalBalanceDec2020M,
      fill: REGION_COLORS[s.region],
      name: s.state,
    }));
  }, [region]);

  const ageBars = useMemo(
    () =>
      AGE_PREVALENCE.map((a) => ({
        age: a.age,
        mar2022: a.mar2022Pct,
        jun2023: a.jun2023Pct,
      })),
    [],
  );

  const scoreLift = useMemo(
    () =>
      SCORE_PATH.map((r) => ({
        group: r.group.replace(" Aug 2022", ""),
        aug2022: r.aug2022,
        aug2023: r.aug2023,
      })),
    [],
  );

  const valueLabel =
    sortKey === "prev2020" || sortKey === "prev2024"
      ? "% of credit records"
      : sortKey === "totalBal"
        ? "Total $M (Dec 2020)"
        : "Mean $ among holders";

  const scoreValueLabel =
    scoreMetric === "prevalence"
      ? "% of band with medical collection (Jun 2023, desk)"
      : scoreMetric === "holders"
        ? "% of medical holders in band"
        : "Mean balance among holders ($)";

  return (
    <div className="overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-gradient-to-r from-slate-900 via-slate-800 to-teal-900 px-4 py-3 sm:px-5">
        <p className="text-[11px] font-semibold uppercase tracking-wider text-teal-200/90">
          Medical collections on credit files
        </p>
        <p className="mt-1 text-sm text-slate-200 sm:text-base">
          {HEADLINE.medicalTradelineSharePctQ2_2021}% of collections tradelines were
          medical (Q2 2021); {fmtPct(HEADLINE.consumersWithMedicalPctAug2024)} of
          consumers still carried one in Aug 2024 ??? Oklahoma {fmtPct(HEADLINE.oklahomaPrevalenceAug2024Pct, 1)}.
        </p>
      </div>

      <div className="flex flex-col gap-3 border-b border-slate-100 px-4 py-3 sm:px-5">
        <ToggleRow
          label="View"
          value={view}
          onChange={setView}
          options={[
            { id: "path", label: "Prevalence path" },
            { id: "mix", label: "Collections mix" },
            { id: "states", label: "State ladder" },
            { id: "scores", label: "Score bands" },
            { id: "scatter", label: "Prev ?? balance" },
            { id: "age", label: "Age + score lift" },
          ]}
        />
        {(view === "states" || view === "scatter") && (
          <ToggleRow
            label="Region"
            value={region}
            onChange={setRegion}
            options={[
              { id: "all", label: "All" },
              { id: "south", label: "South" },
              { id: "midwest", label: "Midwest" },
              { id: "northeast", label: "Northeast" },
              { id: "west", label: "West" },
            ]}
          />
        )}
        {view === "states" && (
          <ToggleRow
            label="Sort"
            value={sortKey}
            onChange={setSortKey}
            options={[
              { id: "prev2024", label: "Aug 2024 %" },
              { id: "prev2020", label: "Dec 2020 %" },
              { id: "totalBal", label: "Total $M" },
              { id: "meanBal", label: "Mean $" },
            ]}
          />
        )}
        {view === "scores" && (
          <ToggleRow
            label="Metric"
            value={scoreMetric}
            onChange={setScoreMetric}
            options={[
              { id: "prevalence", label: "Within-band %" },
              { id: "holders", label: "Holder mix" },
              { id: "balance", label: "Mean balance" },
            ]}
          />
        )}
      </div>

      <div className="px-2 pb-2 pt-4 sm:px-4">
        {view === "path" && (
          <div className="h-[360px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart data={pathData} margin={{ top: 8, right: 16, left: 0, bottom: 8 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="label" tick={{ fontSize: 11 }} interval={0} angle={-25} textAnchor="end" height={60} />
                <YAxis tick={{ fontSize: 11 }} unit="%" />
                <Tooltip formatter={(v) => [`${Number(v).toFixed(1)}%`, "Share with medical"]} />
                <Area type="monotone" dataKey="sharePct" fill={TEAL} fillOpacity={0.2} stroke="none" />
                <Line type="monotone" dataKey="sharePct" stroke={TEAL} strokeWidth={2.5} dot={{ r: 3 }} name="Share %" />
              </ComposedChart>
            </ResponsiveContainer>
          </div>
        )}

        {view === "mix" && (
          <div className="grid gap-4 md:grid-cols-2">
            <div className="h-[300px]">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={mixPie}
                    dataKey="value"
                    nameKey="name"
                    cx="50%"
                    cy="50%"
                    innerRadius={55}
                    outerRadius={95}
                    paddingAngle={2}
                    label={({ name, value }) => `${name} ${value}%`}
                  >
                    {mixPie.map((d) => (
                      <Cell key={d.name} fill={d.fill} />
                    ))}
                  </Pie>
                  <Tooltip formatter={(v) => [`${v}%`, "Tradeline share"]} />
                </PieChart>
              </ResponsiveContainer>
            </div>
            <div className="flex flex-col justify-center gap-3 px-2 text-sm text-slate-600">
              <p>
                Medical debt is the plurality of <em>collections tradelines</em> on
                credit files ??? {HEADLINE.medicalTradelineSharePctQ2_2021}% in Q2 2021
                (CFPB), still ~{HEADLINE.medicalTradelineSharePct2022}% in the 2023
                Market Snapshot ??? even though many items are small-dollar.
              </p>
              <p>
                After the 2022???23 reporting changes, national medical balances on the
                CCP bureau fell about {HEADLINE.balanceDeclineMar22ToJun23Pct}% to
                roughly {fmtUsd(HEADLINE.medicalBalancesJun2023B * 1e9)} (Jun 2023,
                one CRA ??? a lower bound).
              </p>
              <ul className="space-y-1 text-xs text-slate-500">
                {COLLECTION_MIX.map((r) => (
                  <li key={r.type}>
                    <span className="font-semibold text-slate-700">{r.type}:</span>{" "}
                    {r.note}
                  </li>
                ))}
              </ul>
            </div>
          </div>
        )}

        {view === "states" && (
          <div className="h-[420px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                layout="vertical"
                data={stateBars}
                margin={{ top: 4, right: 24, left: 8, bottom: 4 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" horizontal={false} />
                <XAxis type="number" tick={{ fontSize: 11 }} />
                <YAxis type="category" dataKey="abbr" width={36} tick={{ fontSize: 11 }} />
                <Tooltip
                  formatter={(v) => [
                    sortKey === "totalBal" || sortKey === "meanBal"
                      ? fmtUsd(Number(v) * (sortKey === "totalBal" ? 1e6 : 1))
                      : fmtPct(Number(v)),
                    valueLabel,
                  ]}
                  labelFormatter={(_, payload) =>
                    payload?.[0]?.payload?.name ?? ""
                  }
                />
                <Bar dataKey="value" radius={[0, 4, 4, 0]}>
                  {stateBars.map((d) => (
                    <Cell key={d.abbr} fill={d.fill} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
            <p className="mt-1 px-2 text-center text-[11px] text-slate-500">
              Top 15 ?? {valueLabel}
              {region !== "all" ? ` ?? ${REGION_LABELS[region]}` : ""}
            </p>
          </div>
        )}

        {view === "scores" && (
          <div className="grid gap-4 lg:grid-cols-2">
            <div className="h-[300px]">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={scoreBars} margin={{ top: 8, right: 12, left: 0, bottom: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="label" tick={{ fontSize: 11 }} />
                  <YAxis tick={{ fontSize: 11 }} />
                  <Tooltip
                    formatter={(v) => [
                      scoreMetric === "balance"
                        ? fmtUsd(Number(v))
                        : fmtPct(Number(v)),
                      scoreValueLabel,
                    ]}
                  />
                  <Bar dataKey="value" radius={[4, 4, 0, 0]}>
                    {scoreBars.map((d) => (
                      <Cell key={d.label} fill={d.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
              <p className="text-center text-[11px] text-slate-500">{scoreValueLabel}</p>
            </div>
            <div className="h-[300px]">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={scoreCompare} margin={{ top: 8, right: 12, left: 0, bottom: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="label" tick={{ fontSize: 11 }} />
                  <YAxis tick={{ fontSize: 11 }} unit="%" />
                  <Tooltip formatter={(v) => [`${Number(v).toFixed(1)}%`, "Prevalence"]} />
                  <Legend />
                  <Bar dataKey="mar2022" name="Mar 2022" fill={AMBER} radius={[4, 4, 0, 0]} />
                  <Bar dataKey="jun2023" name="Jun 2023" fill={TEAL} radius={[4, 4, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
              <p className="text-center text-[11px] text-slate-500">
                Within-band prevalence before vs after reporting changes (desk)
              </p>
            </div>
          </div>
        )}

        {view === "scatter" && (
          <div className="h-[380px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <ScatterChart margin={{ top: 12, right: 16, left: 8, bottom: 12 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  type="number"
                  dataKey="x"
                  name="Dec 2020 prevalence"
                  unit="%"
                  tick={{ fontSize: 11 }}
                  label={{ value: "Dec 2020 prevalence %", position: "insideBottom", offset: -4, fontSize: 11 }}
                />
                <YAxis
                  type="number"
                  dataKey="y"
                  name="Mean balance"
                  tick={{ fontSize: 11 }}
                  label={{ value: "Mean $ among holders", angle: -90, position: "insideLeft", fontSize: 11 }}
                />
                <ZAxis type="number" dataKey="z" range={[40, 280]} />
                <Tooltip
                  cursor={{ strokeDasharray: "3 3" }}
                  formatter={(v, name) => {
                    if (name === "x" || String(name).includes("prevalence"))
                      return [fmtPct(Number(v)), "Prevalence"];
                    if (name === "y" || String(name).includes("Mean"))
                      return [fmtUsd(Number(v)), "Mean balance"];
                    return [String(v), String(name)];
                  }}
                  labelFormatter={(_, p) => p?.[0]?.payload?.name ?? ""}
                  content={({ active, payload }) => {
                    if (!active || !payload?.[0]) return null;
                    const d = payload[0].payload as {
                      name: string;
                      x: number;
                      y: number;
                      totalM: number;
                    };
                    return (
                      <div className="rounded-md border border-slate-200 bg-white px-3 py-2 text-xs shadow">
                        <p className="font-semibold text-slate-800">{d.name}</p>
                        <p>Prevalence: {fmtPct(d.x)}</p>
                        <p>Mean balance: {fmtUsd(d.y)}</p>
                        <p>Total: {fmtUsd(d.totalM * 1e6)}</p>
                      </div>
                    );
                  }}
                />
                <Scatter data={scatterData}>
                  {scatterData.map((d) => (
                    <Cell key={d.abbr} fill={d.fill} />
                  ))}
                </Scatter>
              </ScatterChart>
            </ResponsiveContainer>
            <p className="text-center text-[11px] text-slate-500">
              Bubble size ??? ???(total medical collections $M), Dec 2020 CFPB Appendix A
            </p>
          </div>
        )}

        {view === "age" && (
          <div className="grid gap-4 lg:grid-cols-2">
            <div className="h-[300px]">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={ageBars} margin={{ top: 8, right: 12, left: 0, bottom: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="age" tick={{ fontSize: 11 }} />
                  <YAxis tick={{ fontSize: 11 }} unit="%" />
                  <Tooltip formatter={(v) => [`${Number(v).toFixed(1)}%`, "Share with medical"]} />
                  <Legend />
                  <Bar dataKey="mar2022" name="Mar 2022" fill={AMBER} radius={[4, 4, 0, 0]} />
                  <Bar dataKey="jun2023" name="Jun 2023" fill={TEAL} radius={[4, 4, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
              <p className="text-center text-[11px] text-slate-500">
                Age prevalence ??? 62+ fell more than two-thirds (CFPB)
              </p>
            </div>
            <div className="h-[300px]">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={scoreLift} margin={{ top: 8, right: 12, left: 0, bottom: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="group" tick={{ fontSize: 10 }} />
                  <YAxis domain={[560, 730]} tick={{ fontSize: 11 }} />
                  <Tooltip />
                  <Legend />
                  <Bar dataKey="aug2022" name="Aug 2022" fill={SLATE} radius={[4, 4, 0, 0]} />
                  <Bar dataKey="aug2023" name="Aug 2023" fill={INDIGO} radius={[4, 4, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
              <p className="text-center text-[11px] text-slate-500">
                Mean VantageScore ??? Urban Wire (holders vs non-holders)
              </p>
            </div>
          </div>
        )}
      </div>

      <p className="border-t border-slate-100 px-4 py-2 text-[10px] leading-relaxed text-slate-400 sm:px-5">
        {SOURCE_NOTE}
      </p>
    </div>
  );
}

success.afterFullFileContent:
"use client";

import { useMemo, useState } from "react";
import {
  Area,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  AGE_PREVALENCE,
  COLLECTION_MIX,
  HEADLINE,
  PREVALENCE_PATH,
  REGION_LABELS,
  SCORE_BANDS,
  SCORE_PATH,
  SOURCE_NOTE,
  STATE_PANEL,
  fmtPct,
  fmtUsd,
  type RegionId,
} from "@/data/medical-debt-in-collections-cfpb-2026-data";

// viz-types: prevalence area+line, collections pie, state horiz bars,
// score-band grouped bars, prevalence??balance scatter, age dual bars
// | layout: default
// controls: view + region filter + state sort + score metric
// smoke-marker: Medical collections on credit files

type ViewId = "path" | "mix" | "states" | "scores" | "scatter" | "age";
type SortKey = "prev2020" | "prev2024" | "totalBal" | "meanBal";
type ScoreMetric = "prevalence" | "holders" | "balance";

const TEAL = "#0d9488";
const AMBER = "#d97706";
const ROSE = "#e11d48";
const SLATE = "#64748b";
const INDIGO = "#4f46e5";
const SKY = "#0284c8";
const REGION_COLORS: Record<RegionId, string> = {
  northeast: INDIGO,
  midwest: SKY,
  south: ROSE,
  west: TEAL,
};

function ToggleRow<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="flex flex-wrap gap-1 rounded-lg bg-slate-100 p-1">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-xs font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

export function MedicalDebtInCollectionsCfpb2026Dashboard() {
  const [view, setView] = useState<ViewId>("path");
  const [region, setRegion] = useState<RegionId | "all">("all");
  const [sortKey, setSortKey] = useState<SortKey>("prev2024");
  const [scoreMetric, setScoreMetric] = useState<ScoreMetric>("prevalence");

  const pathData = useMemo(
    () =>
      PREVALENCE_PATH.map((r) => ({
        label: r.label,
        sharePct: r.sharePct,
      })),
    [],
  );

  const mixPie = useMemo(
    () =>
      COLLECTION_MIX.map((r, i) => ({
        name: r.type,
        value: r.sharePct,
        fill: [ROSE, AMBER, SLATE][i],
      })),
    [],
  );

  const stateBars = useMemo(() => {
    let rows = STATE_PANEL.filter((s) =>
      region === "all" ? true : s.region === region,
    );
    rows = [...rows].sort((a, b) => {
      if (sortKey === "prev2020") return b.prevalenceDec2020Pct - a.prevalenceDec2020Pct;
      if (sortKey === "prev2024")
        return (b.prevalenceAug2024Pct ?? -1) - (a.prevalenceAug2024Pct ?? -1);
      if (sortKey === "totalBal") return b.totalBalanceDec2020M - a.totalBalanceDec2020M;
      return b.meanBalanceDec2020 - a.meanBalanceDec2020;
    });
    return rows.slice(0, 15).map((s) => ({
      abbr: s.abbr,
      name: s.state,
      value:
        sortKey === "prev2020"
          ? s.prevalenceDec2020Pct
          : sortKey === "prev2024"
            ? (s.prevalenceAug2024Pct ?? 0)
            : sortKey === "totalBal"
              ? s.totalBalanceDec2020M
              : s.meanBalanceDec2020,
      fill: REGION_COLORS[s.region],
      prev2020: s.prevalenceDec2020Pct,
      prev2024: s.prevalenceAug2024Pct,
      totalM: s.totalBalanceDec2020M,
      mean: s.meanBalanceDec2020,
    }));
  }, [region, sortKey]);

  const scoreBars = useMemo(() => {
    return SCORE_BANDS.map((b) => {
      let value = b.prevalenceJun2023Pct;
      if (scoreMetric === "prevalence") {
        value = b.prevalenceJun2023Pct;
      } else if (scoreMetric === "holders") {
        value = b.shareOfHoldersPct;
      } else {
        value = b.meanBalanceJun2023;
      }
      return {
        label: b.label,
        value,
        mar: b.prevalenceMar2022Pct,
        jun: b.prevalenceJun2023Pct,
        holders: b.shareOfHoldersPct,
        bal: b.meanBalanceJun2023,
        fill:
          b.id === "deep_subprime"
            ? ROSE
            : b.id === "subprime"
              ? AMBER
              : b.id === "near_prime"
                ? SKY
                : TEAL,
      };
    });
  }, [scoreMetric]);

  const scoreCompare = useMemo(
    () =>
      SCORE_BANDS.map((b) => ({
        label: b.label,
        mar2022: b.prevalenceMar2022Pct,
        jun2023: b.prevalenceJun2023Pct,
      })),
    [],
  );

  const scatterData = useMemo(() => {
    return STATE_PANEL.filter((s) =>
      region === "all" ? true : s.region === region,
    ).map((s) => ({
      abbr: s.abbr,
      x: s.prevalenceDec2020Pct,
      y: s.meanBalanceDec2020,
      z: Math.sqrt(s.totalBalanceDec2020M),
      totalM: s.totalBalanceDec2020M,
      fill: REGION_COLORS[s.region],
      name: s.state,
    }));
  }, [region]);

  const ageBars = useMemo(
    () =>
      AGE_PREVALENCE.map((a) => ({
        age: a.age,
        mar2022: a.mar2022Pct,
        jun2023: a.jun2023Pct,
      })),
    [],
  );

  const scoreLift = useMemo(
    () =>
      SCORE_PATH.map((r) => ({
        group: r.group.replace(" Aug 2022", ""),
        aug2022: r.aug2022,
        aug2023: r.aug2023,
      })),
    [],
  );

  const valueLabel =
    sortKey === "prev2020" || sortKey === "prev2024"
      ? "% of credit records"
      : sortKey === "totalBal"
        ? "Total $M (Dec 2020)"
        : "Mean $ among holders";

  const scoreValueLabel =
    scoreMetric === "prevalence"
      ? "% of band with medical collection (Jun 2023, desk)"
      : scoreMetric === "holders"
        ? "% of medical holders in band"
        : "Mean balance among holders ($)";

  return (
    <div className="overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-gradient-to-r from-slate-900 via-slate-800 to-teal-900 px-4 py-3 sm:px-5">
        <p className="text-[11px] font-semibold uppercase tracking-wider text-teal-200/90">
          Medical collections on credit files
        </p>
        <p className="mt-1 text-sm text-slate-200 sm:text-base">
          {HEADLINE.medicalTradelineSharePctQ2_2021}% of collections tradelines were
          medical (Q2 2021); {fmtPct(HEADLINE.consumersWithMedicalPctAug2024)} of
          consumers still carried one in Aug 2024 ??? Oklahoma {fmtPct(HEADLINE.oklahomaPrevalenceAug2024Pct, 1)}.
        </p>
      </div>

      <div className="flex flex-col gap-3 border-b border-slate-100 px-4 py-3 sm:px-5">
        <ToggleRow
          label="View"
          value={view}
          onChange={setView}
          options={[
            { id: "path", label: "Prevalence path" },
            { id: "mix", label: "Collections mix" },
            { id: "states", label: "State ladder" },
            { id: "scores", label: "Score bands" },
            { id: "scatter", label: "Prev ?? balance" },
            { id: "age", label: "Age + score lift" },
          ]}
        />
        {(view === "states" || view === "scatter") && (
          <ToggleRow
            label="Region"
            value={region}
            onChange={setRegion}
            options={[
              { id: "all", label: "All" },
              { id: "south", label: "South" },
              { id: "midwest", label: "Midwest" },
              { id: "northeast", label: "Northeast" },
              { id: "west", label: "West" },
            ]}
          />
        )}
        {view === "states" && (
          <ToggleRow
            label="Sort"
            value={sortKey}
            onChange={setSortKey}
            options={[
              { id: "prev2024", label: "Aug 2024 %" },
              { id: "prev2020", label: "Dec 2020 %" },
              { id: "totalBal", label: "Total $M" },
              { id: "meanBal", label: "Mean $" },
            ]}
          />
        )}
        {view === "scores" && (
          <ToggleRow
            label="Metric"
            value={scoreMetric}
            onChange={setScoreMetric}
            options={[
              { id: "prevalence", label: "Within-band %" },
              { id: "holders", label: "Holder mix" },
              { id: "balance", label: "Mean balance" },
            ]}
          />
        )}
      </div>

      <div className="px-2 pb-2 pt-4 sm:px-4">
        {view === "path" && (
          <div className="h-[360px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart data={pathData} margin={{ top: 8, right: 16, left: 0, bottom: 8 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="label" tick={{ fontSize: 11 }} interval={0} angle={-25} textAnchor="end" height={60} />
                <YAxis tick={{ fontSize: 11 }} unit="%" />
                <Tooltip formatter={(v) => [`${Number(v).toFixed(1)}%`, "Share with medical"]} />
                <Area type="monotone" dataKey="sharePct" fill={TEAL} fillOpacity={0.2} stroke="none" />
                <Line type="monotone" dataKey="sharePct" stroke={TEAL} strokeWidth={2.5} dot={{ r: 3 }} name="Share %" />
              </ComposedChart>
            </ResponsiveContainer>
          </div>
        )}

        {view === "mix" && (
          <div className="grid gap-4 md:grid-cols-2">
            <div className="h-[300px]">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={mixPie}
                    dataKey="value"
                    nameKey="name"
                    cx="50%"
                    cy="50%"
                    innerRadius={55}
                    outerRadius={95}
                    paddingAngle={2}
                    label={({ name, value }) => `${name} ${value}%`}
                  >
                    {mixPie.map((d) => (
                      <Cell key={d.name} fill={d.fill} />
                    ))}
                  </Pie>
                  <Tooltip formatter={(v) => [`${v}%`, "Tradeline share"]} />
                </PieChart>
              </ResponsiveContainer>
            </div>
            <div className="flex flex-col justify-center gap-3 px-2 text-sm text-slate-600">
              <p>
                Medical debt is the plurality of <em>collections tradelines</em> on
                credit files ??? {HEADLINE.medicalTradelineSharePctQ2_2021}% in Q2 2021
                (CFPB), still ~{HEADLINE.medicalTradelineSharePct2022}% in the 2023
                Market Snapshot ??? even though many items are small-dollar.
              </p>
              <p>
                After the 2022???23 reporting changes, national medical balances on the
                CCP bureau fell about {HEADLINE.balanceDeclineMar22ToJun23Pct}% to
                roughly {fmtUsd(HEADLINE.medicalBalancesJun2023B * 1e9)} (Jun 2023,
                one CRA ??? a lower bound).
              </p>
              <ul className="space-y-1 text-xs text-slate-500">
                {COLLECTION_MIX.map((r) => (
                  <li key={r.type}>
                    <span className="font-semibold text-slate-700">{r.type}:</span>{" "}
                    {r.note}
                  </li>
                ))}
              </ul>
            </div>
          </div>
        )}

        {view === "states" && (
          <div className="h-[420px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                layout="vertical"
                data={stateBars}
                margin={{ top: 4, right: 24, left: 8, bottom: 4 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" horizontal={false} />
                <XAxis type="number" tick={{ fontSize: 11 }} />
                <YAxis type="category" dataKey="abbr" width={36} tick={{ fontSize: 11 }} />
                <Tooltip
                  formatter={(v) => [
                    sortKey === "totalBal" || sortKey === "meanBal"
                      ? fmtUsd(Number(v) * (sortKey === "totalBal" ? 1e6 : 1))
                      : fmtPct(Number(v)),
                    valueLabel,
                  ]}
                  labelFormatter={(_, payload) =>
                    payload?.[0]?.payload?.name ?? ""
                  }
                />
                <Bar dataKey="value" radius={[0, 4, 4, 0]}>
                  {stateBars.map((d) => (
                    <Cell key={d.abbr} fill={d.fill} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
            <p className="mt-1 px-2 text-center text-[11px] text-slate-500">
              Top 15 ?? {valueLabel}
              {region !== "all" ? ` ?? ${REGION_LABELS[region]}` : ""}
            </p>
          </div>
        )}

        {view === "scores" && (
          <div className="grid gap-4 lg:grid-cols-2">
            <div className="h-[300px]">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={scoreBars} margin={{ top: 8, right: 12, left: 0, bottom: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="label" tick={{ fontSize: 11 }} />
                  <YAxis tick={{ fontSize: 11 }} />
                  <Tooltip
                    formatter={(v) => [
                      scoreMetric === "balance"
                        ? fmtUsd(Number(v))
                        : fmtPct(Number(v)),
                      scoreValueLabel,
                    ]}
                  />
                  <Bar dataKey="value" radius={[4, 4, 0, 0]}>
                    {scoreBars.map((d) => (
                      <Cell key={d.label} fill={d.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
              <p className="text-center text-[11px] text-slate-500">{scoreValueLabel}</p>
            </div>
            <div className="h-[300px]">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={scoreCompare} margin={{ top: 8, right: 12, left: 0, bottom: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="label" tick={{ fontSize: 11 }} />
                  <YAxis tick={{ fontSize: 11 }} unit="%" />
                  <Tooltip formatter={(v) => [`${Number(v).toFixed(1)}%`, "Prevalence"]} />
                  <Legend />
                  <Bar dataKey="mar2022" name="Mar 2022" fill={AMBER} radius={[4, 4, 0, 0]} />
                  <Bar dataKey="jun2023" name="Jun 2023" fill={TEAL} radius={[4, 4, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
              <p className="text-center text-[11px] text-slate-500">
                Within-band prevalence before vs after reporting changes (desk)
              </p>
            </div>
          </div>
        )}

        {view === "scatter" && (
          <div className="h-[380px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <ScatterChart margin={{ top: 12, right: 16, left: 8, bottom: 12 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  type="number"
                  dataKey="x"
                  name="Dec 2020 prevalence"
                  unit="%"
                  tick={{ fontSize: 11 }}
                  label={{ value: "Dec 2020 prevalence %", position: "insideBottom", offset: -4, fontSize: 11 }}
                />
                <YAxis
                  type="number"
                  dataKey="y"
                  name="Mean balance"
                  tick={{ fontSize: 11 }}
                  label={{ value: "Mean $ among holders", angle: -90, position: "insideLeft", fontSize: 11 }}
                />
                <ZAxis type="number" dataKey="z" range={[40, 280]} />
                <Tooltip
                  cursor={{ strokeDasharray: "3 3" }}
                  formatter={(v, name) => {
                    if (name === "x" || String(name).includes("prevalence"))
                      return [fmtPct(Number(v)), "Prevalence"];
                    if (name === "y" || String(name).includes("Mean"))
                      return [fmtUsd(Number(v)), "Mean balance"];
                    return [String(v), String(name)];
                  }}
                  labelFormatter={(_, p) => p?.[0]?.payload?.name ?? ""}
                  content={({ active, payload }) => {
                    if (!active || !payload?.[0]) return null;
                    const d = payload[0].payload as {
                      name: string;
                      x: number;
                      y: number;
                      totalM: number;
                    };
                    return (
                      <div className="rounded-md border border-slate-200 bg-white px-3 py-2 text-xs shadow">
                        <p className="font-semibold text-slate-800">{d.name}</p>
                        <p>Prevalence: {fmtPct(d.x)}</p>
                        <p>Mean balance: {fmtUsd(d.y)}</p>
                        <p>Total: {fmtUsd(d.totalM * 1e6)}</p>
                      </div>
                    );
                  }}
                />
                <Scatter data={scatterData}>
                  {scatterData.map((d) => (
                    <Cell key={d.abbr} fill={d.fill} />
                  ))}
                </Scatter>
              </ScatterChart>
            </ResponsiveContainer>
            <p className="text-center text-[11px] text-slate-500">
              Bubble size ??? ???(total medical collections $M), Dec 2020 CFPB Appendix A
            </p>
          </div>
        )}

        {view === "age" && (
          <div className="grid gap-4 lg:grid-cols-2">
            <div className="h-[300px]">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={ageBars} margin={{ top: 8, right: 12, left: 0, bottom: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="age" tick={{ fontSize: 11 }} />
                  <YAxis tick={{ fontSize: 11 }} unit="%" />
                  <Tooltip formatter={(v) => [`${Number(v).toFixed(1)}%`, "Share with medical"]} />
                  <Legend />
                  <Bar dataKey="mar2022" name="Mar 2022" fill={AMBER} radius={[4, 4, 0, 0]} />
                  <Bar dataKey="jun2023" name="Jun 2023" fill={TEAL} radius={[4, 4, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
              <p className="text-center text-[11px] text-slate-500">
                Age prevalence ??? 62+ fell more than two-thirds (CFPB)
              </p>
            </div>
            <div className="h-[300px]">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={scoreLift} margin={{ top: 8, right: 12, left: 0, bottom: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="group" tick={{ fontSize: 10 }} />
                  <YAxis domain={[560, 730]} tick={{ fontSize: 11 }} />
                  <Tooltip />
                  <Legend />
                  <Bar dataKey="aug2022" name="Aug 2022" fill={SLATE} radius={[4, 4, 0, 0]} />
                  <Bar dataKey="aug2023" name="Aug 2023" fill={INDIGO} radius={[4, 4, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
              <p className="text-center text-[11px] text-slate-500">
                Mean VantageScore ??? Urban Wire (holders vs non-holders)
              </p>
            </div>
          </div>
        )}
      </div>

      <p className="border-t border-slate-100 px-4 py-2 text-[10px] leading-relaxed text-slate-400 sm:px-5">
        {SOURCE_NOTE}
      </p>
    </div>
  );
}

