/**
 * QA: medical-debt-in-collections-cfpb-2026
 * // viz-types: prevalence area+line, collections pie, state horiz bars,
 * // score-band grouped bars, prevalence??balance scatter, age dual bars
 * // | layout: default
 * // smoke-marker: Medical collections on credit files
 */
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { chromium } from "playwright";
import { startStaticServer, stopStaticServer } from "./lib/static-server.mjs";
import { auditVizInteractions } from "./lib/viz-interaction-qa.mjs";
import {
  COLLECTION_MIX,
  HEADLINE,
  PREVALENCE_PATH,
  SCORE_BANDS,
  STATE_PANEL,
} from "../src/data/medical-debt-in-collections-cfpb-2026-data.ts";

assert.equal(HEADLINE.medicalTradelineSharePctQ2_2021, 58);
assert.equal(HEADLINE.consumersWithMedicalPctJun2023, 5);
assert.equal(HEADLINE.consumersWithMedicalPctAug2024, 4.1);
assert.equal(HEADLINE.oklahomaPrevalenceAug2024Pct, 8.8);
assert.equal(HEADLINE.medicalBalancesJun2023B, 49.2);
assert.ok(STATE_PANEL.length >= 50);
assert.ok(PREVALENCE_PATH.length >= 8);
assert.ok(SCORE_BANDS.length >= 4);
assert.ok(COLLECTION_MIX.length >= 3);

const root = process.cwd();
const slug = "medical-debt-in-collections-cfpb-2026";
const markers = [
  "Medical collections on credit files",
  "Medical Debt Still Dominates Collections Tradelines",
];

async function clickBtn(page, name) {
  console.log(`??? click ${name}`);
  await page.locator("button", { hasText: name }).first().click({ timeout: 8000 });
  await page.waitForTimeout(200);
}

async function main() {
  const outDir = path.join(root, "out");
  if (!fs.existsSync(outDir)) {
    console.error("??? Missing out/ ??? run npm run build first");
    process.exit(1);
  }
  const port = Number(process.env.SMOKE_PORT || 4182);
  const server = await startStaticServer(outDir, port);
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  page.setDefaultTimeout(15000);
  try {
    await page.goto(`http://127.0.0.1:${port}/blog/${slug}.html`, {
      waitUntil: "domcontentloaded",
      timeout: 45000,
    });
    await page.waitForSelector(`[data-viz="${slug}"]`, { timeout: 20000 });
    for (const m of markers) {
      await page.getByText(m, { exact: false }).first().waitFor({ timeout: 20000 });
      console.log(`??? ${m}`);
    }
    await clickBtn(page, "Prevalence path");
    await clickBtn(page, "Collections mix");
    await clickBtn(page, "State ladder");
    await clickBtn(page, "Aug 2024 %");
    await clickBtn(page, "Dec 2020 %");
    await clickBtn(page, "South");
    await clickBtn(page, "All");
    await clickBtn(page, "Score bands");
    await clickBtn(page, "Within-band %");
    await clickBtn(page, "Holder mix");
    await clickBtn(page, "Prev ?? balance");
    await clickBtn(page, "Age + score lift");
    await clickBtn(page, "Prevalence path");
    await auditVizInteractions(page, {
      slug,
      maxButtons: 20,
      maxCharts: 4,
    });
    console.log("??? QA passed:", slug);
  } finally {
    await browser.close();
    await stopStaticServer(server);
  }
}

main().catch((err) => {
  console.error("??? QA failed:", err);
  process.exit(1);
});

